pipeline {
    agent any

    environment {
        GROUP_NAME = 'com.dsj'
        PROJECT_NAME = 'result-transformation'
        VERSION = '1.0.0'
        REMOTE_HOST = '20.48.1.67'
        REMOTE_USER = 'root'
        REMOTE_CREDENTIALS_ID = 'jenkins-server-ssh-private-key'
        TIMESTAMP = new Date().format("yyyyMMddHHmmss", TimeZone.getTimeZone('Asia/Shanghai'))
        IMAGE_TAG = "${GROUP_NAME}/${PROJECT_NAME}:${VERSION}"
        REGISTRY_TAG = "${DOCKER_REGISTRY}/${PROJECT_NAME}:${VERSION}-${TIMESTAMP}"
    }

    stages {
        stage('Git Checkout') {
            steps {
                echo "Checking out code from branch: ${params.Branch}"
                checkout scmGit(
                    branches: [[name: "${params.Branch}"]],
                    extensions: [[$class: 'CleanBeforeCheckout']],
                    userRemoteConfigs: [[
                        credentialsId: 'SSH-KEY-FOR-GITLAB',
                        url: "${GIALAB_ADDRESS}/dengbin/result-transformation.git"
                    ]]
                )
            }
        }

        stage('Mvn Build') {
            // tools {
            //     jdk 'jdk1.8'
            // }
            steps {
                sh 'mvn -T 4 clean package -Dmaven.test.skip=true -Pdev'
            }
        }

        stage('Build Image') {
            steps {
                sh "docker rmi ${IMAGE_TAG} || true"
                sh "docker build -t ${IMAGE_TAG} -f devops/Dockerfile ."
            }
        }

        stage('Push Image') {
            steps {
                sh "docker login --username=${DOCKER_REGISTRY_USERNAME} --password=${DOCKER_REGISTRY_PASSWORD} ${DOCKER_REGISTRY}"
                sh "docker tag ${IMAGE_TAG} ${REGISTRY_TAG}"
                sh "docker push ${REGISTRY_TAG}"
            }
        }

        stage('Deploy') {
            when {
                expression { return params.DEPLOY }
            }
            steps {
                sshagent([REMOTE_CREDENTIALS_ID]) {
                    sh """
                        ssh -o StrictHostKeyChecking=no ${REMOTE_USER}@${REMOTE_HOST} '
                            set -e
                            echo "Deploying ${REGISTRY_TAG}"
                            docker login --username=${DOCKER_REGISTRY_USERNAME} --password=${DOCKER_REGISTRY_PASSWORD} ${DOCKER_REGISTRY}
                            docker pull ${REGISTRY_TAG}
                            docker rm -f ${PROJECT_NAME} || true
                            docker run -d \
                                --name ${PROJECT_NAME} \
                                --restart=on-failure:5 \
                                -e TZ=Asia/Shanghai \
                                -p 30000:30000 \
                                ${REGISTRY_TAG}
                            echo "Deployment completed"
                        '
                    """
                }
            }
        }
    }
}
